public class SwitchExpressionDemo {
    public enum Day { MONDAY, TUESDAY, FRIDAY, SATURDAY }

    public static int calculateWorkHours(Day day, boolean isRemote) {
        // Combining arrow syntax, multiple constants, and yield blocks
        return switch (day) {
            case MONDAY, TUESDAY, FRIDAY -> 8;
            case SATURDAY -> 0;
            default -> {
                System.out.println("Calculating complex schedule for mid-week...");
                int baseHours = isRemote ? 6 : 8;
                // yield returns the value from this block-scoped case branch
                yield baseHours + 2;
            }
        };
    }
}
